import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice enriches multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[1].name, 'Logo package');
});

test('createInvoice rejects an unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice validates date format', () => {
  const cases = [
    '2026-13-01', // invalid month
    '2026-02-30', // invalid day
    '2026-2-01', // missing leading zero
    'not-a-date',
    '2026/10/07',
    undefined,
  ];
  for (const issueDate of cases) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' }, `should reject ${issueDate}`);
  }
});

test('createInvoice accepts valid dates', () => {
  const cases = ['2026-01-01', '2026-12-31', '2000-02-29'];
  for (const issueDate of cases) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    assert.equal(r.ok, true, `should accept ${issueDate}`);
  }
});

test('createInvoice rejects an empty lines array', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects non-array lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: null,
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice validates line quantities', () => {
  const cases = [
    { qty: 0 },
    { qty: -1 },
    { qty: 1.5 },
    { qty: '5' },
    { qty: null },
  ];
  for (const line of cases) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', ...line }],
    });
    assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' }, `should reject qty=${line.qty}`);
  }
});

test('createInvoice rejects unknown SKUs', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'NOPE', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate input lines', () => {
  const input = [{ sku: 'DES-HOUR', qty: 1 }];
  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: input,
  });
  assert.deepEqual(input, [{ sku: 'DES-HOUR', qty: 1 }]);
});

test('createInvoice returns a new object', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.notStrictEqual(r1.value, r2.value);
  assert.notStrictEqual(r1.value.lines, r2.value.lines);
});

test('lineTotal calculates qty × unitPrice', () => {
  const r = lineTotal({ qty: 5, unitPrice: 8500 });
  assert.equal(r.ok, true);
  assert.equal(r.value, 42500);
});

test('lineTotal handles various quantities and prices', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 100 }).value, 100);
  assert.equal(lineTotal({ qty: 10, unitPrice: 1000 }).value, 10000);
  assert.equal(lineTotal({ qty: 3, unitPrice: 120000 }).value, 360000);
});

test('lineTotal validates qty is a positive integer', () => {
  const cases = [
    { qty: 0, error: 'QTY_INVALID' },
    { qty: -5, error: 'QTY_INVALID' },
    { qty: 1.5, error: 'QTY_INVALID' },
    { qty: '5', error: 'QTY_INVALID' },
    { qty: null, error: 'QTY_INVALID' },
  ];
  for (const c of cases) {
    const r = lineTotal({ qty: c.qty, unitPrice: 100 });
    assert.deepEqual(r, { ok: false, error: c.error }, `should reject qty=${c.qty}`);
  }
});

test('lineTotal validates unitPrice is a non-negative integer', () => {
  const cases = [
    { unitPrice: -100, error: 'AMOUNT_INVALID' },
    { unitPrice: 1.5, error: 'AMOUNT_INVALID' },
    { unitPrice: '100', error: 'AMOUNT_INVALID' },
    { unitPrice: null, error: 'AMOUNT_INVALID' },
  ];
  for (const c of cases) {
    const r = lineTotal({ qty: 1, unitPrice: c.unitPrice });
    assert.deepEqual(r, { ok: false, error: c.error }, `should reject unitPrice=${c.unitPrice}`);
  }
});

test('lineTotal accepts zero unitPrice', () => {
  const r = lineTotal({ qty: 5, unitPrice: 0 });
  assert.equal(r.ok, true);
  assert.equal(r.value, 0);
});

test('invoiceTotals calculates subtotal, discount, vat and total', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, vatRate: 21 },
      { qty: 1, unitPrice: 120000, vatRate: 21 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 162500);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 34125);
  assert.equal(r.value.total, 196625);
});

test('invoiceTotals sums multiple line totals', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 100, vatRate: 21 },
      { qty: 2, unitPrice: 200, vatRate: 21 },
      { qty: 1, unitPrice: 500, vatRate: 21 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 1200);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 252);
  assert.equal(r.value.total, 1452);
});

test('invoiceTotals returns an object with subtotal, discount, vat and total', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 100, vatRate: 21 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.ok('subtotal' in r.value);
  assert.ok('discount' in r.value);
  assert.ok('vat' in r.value);
  assert.ok('total' in r.value);
});

test('invoiceTotals validates invoice has lines', () => {
  const cases = [null, {}, { lines: null }, { lines: [] }];
  for (const invoice of cases) {
    const r = invoiceTotals(invoice);
    assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
  }
});

test('invoiceTotals propagates line validation errors', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 100 },
      { qty: 0, unitPrice: 100 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('invoiceTotals works with real invoices from createInvoice', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(invoice.ok, true);
  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 5 * 8500 + 1 * 120000);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 34125);
  assert.equal(r.value.total, 196625);
});

test('createInvoice accepts and stores discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
