test('createInvoice accepts 0 and 100 discountPercent', () => {
  const r0 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
