  assert.equal(r.value.discount, 0);
  const vat21 = Math.round(5000 * 0.21);
  const vat9 = Math.round(2000 * 0.09);
  const vat0 = Math.round(1000 * 0.00);
  const expectedVat = vat21 + vat9 + vat0;
  const expectedTotal = 8000 + expectedVat;
  assert.equal(r.value.vat, expectedVat);
  assert.equal(r.value.total, expectedTotal);
});

test('invoiceTotals VAT is rounded per line', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 100, vatRate: 21 },
      { qty: 3, unitPrice: 100, vatRate: 21 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 600);
  const vat1 = Math.round(300 * 0.21);
  const vat2 = Math.round(300 * 0.21);
  const expectedVat = vat1 + vat2;
  assert.equal(r.value.vat, expectedVat);
});

test('invoiceTotals zero VAT rate results in no VAT', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 0 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 10000);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 0);
  assert.equal(r.value.total, 10000);
});

